{"file_text":"/**
 * System-Assigned Managed Identity Example
 * 
 * System-assigned identities are tied to the lifecycle of the Azure resource.
 * When the resource is deleted, the identity is automatically deleted.
 */

import { ManagedIdentityCredential, DefaultAzureCredential } from "@azure/identity";
import { SecretClient } from "@azure/keyvault-secrets";
import { BlobServiceClient } from "@azure/storage-blob";
import { CosmosClient } from "@azure/cosmos";

// ============================================================================
// 1. BASIC SYSTEM-ASSIGNED MANAGED IDENTITY
// ============================================================================

/**
 * Creates a ManagedIdentityCredential for system-assigned identity.
 * No parameters needed - uses the identity attached to the Azure resource.
 */
function createSystemAssignedCredential(): ManagedIdentityCredential {
  return new ManagedIdentityCredential();
}

// ============================================================================
// 2. USING WITH AZURE SDK CLIENTS
// ============================================================================

/**
 * Example: Using system-assigned identity with Key Vault
 */
async function accessKeyVaultWithSystemIdentity(): Promise<void> {
  const credential = new ManagedIdentityCredential();
  const vaultUrl = "https://my-keyvault.vault.azure.net";

  const client = new SecretClient(vaultUrl, credential);

  try {
    const secret = await client.getSecret("my-secret-name");
    console.log("Secret retrieved:", secret.name);
    console.log("Secret value:", secret.value);
  } catch (error) {
    console.error("Error accessing Key Vault:", error);
    throw error;
  }
}

/**
 * Example: Using system-assigned identity with Blob Storage
 */
async function accessBlobStorageWithSystemIdentity(): Promise<void> {
  const credential = new ManagedIdentityCredential();
  const storageAccountUrl = "https://mystorageaccount.blob.core.windows.net";

  const blobServiceClient = new BlobServiceClient(
    storageAccountUrl,
    credential
  );

  try {
    const containerClient = blobServiceClient.getContainerClient("my-container");

    // List blobs in the container
    for await (const blob of containerClient.listBlobsFlat()) {
      console.log(`Blob: ${blob.name}`);
    }
  } catch (error) {
    console.error("Error accessing Blob Storage:", error);
    throw error;
  }
}

/**
 * Example: Using system-assigned identity with Cosmos DB
 */
async function accessCosmosDBWithSystemIdentity(): Promise<void> {
  const credential = new ManagedIdentityCredential();
  const endpoint = "https://mycosmosdb.documents.azure.com:443/";

  const client = new CosmosClient({
    endpoint,
    aadCredentials: credential
  });

  try {
    const { database } = await client.databases.createIfNotExists({
      id: "my-database"
    });
    console.log("Database accessed:", database.id);
  } catch (error) {
    console.error("Error accessing Cosmos DB:", error);
    throw error;
  }
}

// ============================================================================
// 3. LOCAL DEVELOPMENT FALLBACK - DEFAULT AZURE CREDENTIAL
// ============================================================================

/**
 * DefaultAzureCredential provides automatic fallback for local development.
 * It tries credentials in this order:
 * 1. EnvironmentCredential (env variables)
 * 2. WorkloadIdentityCredential (Kubernetes)
 * 3. ManagedIdentityCredential (Azure resources)
 * 4. AzureCliCredential (local Azure CLI)
 * 5. AzurePowerShellCredential (local Azure PowerShell)
 * 6. AzureDeveloperCliCredential (local azd)
 */
async function useDefaultAzureCredential(): Promise<void> {
  // This works both in Azure (managed identity) and locally (Azure CLI)
  const credential = new DefaultAzureCredential();
  const vaultUrl = "https://my-keyvault.vault.azure.net";

  const client = new SecretClient(vaultUrl, credential);

  try {
    const secret = await client.getSecret("my-secret-name");
    console.log("Secret retrieved:", secret.name);
  } catch (error) {
    console.error("Authentication failed:", error);
    throw error;
  }
}

// ============================================================================
// 4. MANUAL LOCAL DEVELOPMENT FALLBACK
// ============================================================================

/**
 * Manual fallback strategy - try managed identity first, then Azure CLI
 */
async function manualFallbackStrategy(): Promise<void> {
  const { AzureCliCredential } = require("@azure/identity");

  // Detect if running in Azure (common env variables)
  const isRunningInAzure = 
    process.env.WEBSITE_INSTANCE_ID || // App Service
    process.env.CONTAINER_APP_NAME ||  // Container Apps
    process.env.FUNCTIONS_WORKER_RUNTIME; // Functions

  const credential = isRunningInAzure
    ? new ManagedIdentityCredential()
    : new AzureCliCredential();

  const vaultUrl = "https://my-keyvault.vault.azure.net";
  const client = new SecretClient(vaultUrl, credential);

  try {
    const secret = await client.getSecret("my-secret-name");
    console.log("Secret retrieved using:", isRunningInAzure ? "Managed Identity" : "Azure CLI");
  } catch (error) {
    console.error("Authentication failed:", error);
    throw error;
  }
}

// ============================================================================
// 5. ERROR HANDLING AND COMMON PITFALLS
// ============================================================================

/**
 * Comprehensive error handling for managed identity
 */
async function robustManagedIdentityUsage(): Promise<void> {
  const vaultUrl = "https://my-keyvault.vault.azure.net";

  try {
    const credential = new ManagedIdentityCredential();
    const client = new SecretClient(vaultUrl, credential);

    const secret = await client.getSecret("my-secret-name");
    console.log("Success:", secret.name);

  } catch (error: any) {
    // Handle specific error scenarios
    if (error.code === "ManagedIdentityCredential_Timeout") {
      console.error("Timeout: Managed identity endpoint not responding");
      console.error("Possible cause: Not running on Azure resource with managed identity enabled");
    } else if (error.code === "CredentialUnavailable") {
      console.error("Managed identity not available");
      console.error("Ensure managed identity is enabled on your Azure resource");
    } else if (error.statusCode === 403) {
      console.error("Access denied: Managed identity lacks required permissions");
      console.error("Grant appropriate RBAC role to the managed identity");
    } else if (error.statusCode === 404) {
      console.error("Resource not found or managed identity lacks access");
    } else {
      console.error("Unexpected error:", error.message);
      console.error("Full error:", error);
    }

    throw error;
  }
}

/**
 * Testing managed identity availability
 */
async function testManagedIdentityAvailability(): Promise<boolean> {
  try {
    const credential = new ManagedIdentityCredential();

    // Try to get a token for Azure Resource Manager
    const token = await credential.getToken("https://management.azure.com/.default");

    if (token && token.token) {
      console.log("✓ Managed identity is available and working");
      console.log("Token expires at:", new Date(token.expiresOnTimestamp));
      return true;
    }

    return false;
  } catch (error: any) {
    console.log("✗ Managed identity is not available:", error.message);
    return false;
  }
}

// ============================================================================
// 6. COMMON PITFALLS
// ============================================================================

/**
 * PITFALL #1: Not enabling managed identity on the Azure resource
 * Solution: Enable it via Azure Portal, CLI, or ARM template
 */

/**
 * PITFALL #2: Missing RBAC permissions
 * Solution: Assign appropriate role (e.g., "Key Vault Secrets User")
 * Example Azure CLI command:
 * 
 * az role assignment create \
 *   --assignee <managed-identity-principal-id> \
 *   --role "Key Vault Secrets User" \
 *   --scope /subscriptions/<sub-id>/resourceGroups/<rg>/providers/Microsoft.KeyVault/vaults/<vault>
 */

/**
 * PITFALL #3: Using wrong endpoint in multi-cloud scenarios
 * Solution: Use DefaultAzureCredential with explicit options
 */
function multiCloudCredential(): ManagedIdentityCredential {
  return new ManagedIdentityCredential({
    // For Azure Government
    // authorityHost: "https://login.microsoftonline.us"

    // For Azure China
    // authorityHost: "https://login.chinacloudapi.cn"
  });
}

/**
 * PITFALL #4: Forgetting token caching
 * Good news: @azure/identity handles token caching automatically!
 * Tokens are cached and refreshed automatically before expiration.
 */

/**
 * PITFALL #5: Long startup time on first request
 * Solution: Warm up the credential during app initialization
 */
async function warmUpCredential(credential: ManagedIdentityCredential): Promise<void> {
  try {
    console.log("Warming up managed identity credential...");
    await credential.getToken("https://management.azure.com/.default");
    console.log("Credential ready!");
  } catch (error) {
    console.warn("Failed to warm up credential:", error);
  }
}

// ============================================================================
// COMPLETE EXAMPLE: AZURE FUNCTION WITH SYSTEM-ASSIGNED IDENTITY
