interface HttpRequest {
  query: { secretName?: string };
}

interface HttpResponse {
  status: number;
  body: string;
}

/**
 * Azure Function example using system-assigned managed identity
 */
export async function httpTrigger(
  context: any,
  req: HttpRequest
): Promise<HttpResponse> {
  const secretName = req.query.secretName || "default-secret";

  try {
    // Use DefaultAzureCredential for both Azure and local development
    const credential = new DefaultAzureCredential();
    const vaultUrl = process.env.KEY_VAULT_URL || "https://my-keyvault.vault.azure.net";

    const client = new SecretClient(vaultUrl, credential);
    const secret = await client.getSecret(secretName);

    return {
      status: 200,
      body: JSON.stringify({
        message: "Secret retrieved successfully",
        secretName: secret.name,
        // Never return the actual secret value in production!
        hasValue: !!secret.value
      })
    };

  } catch (error: any) {
    console.error("Error retrieving secret:", error);

    return {
      status: error.statusCode || 500,
      body: JSON.stringify({
        error: "Failed to retrieve secret",
        message: error.message
      })
    };
  }
}

// Export examples
export {
  createSystemAssignedCredential,
  accessKeyVaultWithSystemIdentity,
  accessBlobStorageWithSystemIdentity,
  accessCosmosDBWithSystemIdentity,
  useDefaultAzureCredential,
  manualFallbackStrategy,
  robustManagedIdentityUsage,
  testManagedIdentityAvailability,
  warmUpCredential
};
