import { ManagedIdentityCredential, DefaultAzureCredential } from "@azure/identity";
import { SecretClient } from "@azure/keyvault-secrets";
import { BlobServiceClient } from "@azure/storage-blob";

// ============================================================================
// 1. BASIC USER-ASSIGNED MANAGED IDENTITY
// ============================================================================

/**
 * Creates a ManagedIdentityCredential using CLIENT ID
 * This is the most common way to specify user-assigned identity
 */
function createUserAssignedCredentialByClientId(clientId: string): ManagedIdentityCredential {
  return new ManagedIdentityCredential({
    clientId: clientId  // The Application (client) ID of the managed identity
  });
}

/**
 * Creates a ManagedIdentityCredential using RESOURCE ID
 * Use when you have the full Azure Resource Manager resource ID
 */
function createUserAssignedCredentialByResourceId(resourceId: string): ManagedIdentityCredential {
  return new ManagedIdentityCredential({
    resourceId: resourceId
    // Example: /subscriptions/{sub-id}/resourceGroups/{rg}/providers/Microsoft.ManagedIdentity/userAssignedIdentities/{name}
  });
}

/**
 * Creates a ManagedIdentityCredential using OBJECT ID (Principal ID)
 * Less common, but useful in some scenarios
 */
function createUserAssignedCredentialByObjectId(objectId: string): ManagedIdentityCredential {
  return new ManagedIdentityCredential({
    // Note: The SDK might not support objectId directly in all versions
    // Use clientId instead when possible
    clientId: objectId
  });
}

// ============================================================================
// 2. USING USER-ASSIGNED IDENTITY WITH AZURE SDK CLIENTS
// ============================================================================

/**
 * Example: Using user-assigned identity with Key Vault
 */
async function accessKeyVaultWithUserAssignedIdentity(): Promise<void> {
  // Get the client ID from environment variable (recommended)
  const clientId = process.env.MANAGED_IDENTITY_CLIENT_ID;

  if (!clientId) {
    throw new Error("MANAGED_IDENTITY_CLIENT_ID environment variable not set");
  }

  const credential = new ManagedIdentityCredential({ clientId });
  const vaultUrl = "https://my-keyvault.vault.azure.net";

  const client = new SecretClient(vaultUrl, credential);

  try {
    const secret = await client.getSecret("my-secret-name");
    console.log("Secret retrieved:", secret.name);
    console.log("Using user-assigned identity:", clientId);
  } catch (error) {
    console.error("Error accessing Key Vault:", error);
    throw error;
  }
}

/**
 * Example: Multiple user-assigned identities on the same resource
 * Choose which identity to use based on the operation
 */
async function useMultipleUserAssignedIdentities(): Promise<void> {
  // Different identities for different services
  const keyVaultIdentityClientId = process.env.KEYVAULT_IDENTITY_CLIENT_ID!;
  const storageIdentityClientId = process.env.STORAGE_IDENTITY_CLIENT_ID!;

  // Access Key Vault with one identity
  const kvCredential = new ManagedIdentityCredential({ 
    clientId: keyVaultIdentityClientId 
  });
  const kvClient = new SecretClient(
    "https://my-keyvault.vault.azure.net", 
    kvCredential
  );

  // Access Storage with another identity
  const storageCredential = new ManagedIdentityCredential({ 
    clientId: storageIdentityClientId 
  });
  const blobClient = new BlobServiceClient(
    "https://mystorageaccount.blob.core.windows.net",
    storageCredential
  );

  try {
    const secret = await kvClient.getSecret("my-secret");
    console.log("Secret retrieved with identity:", keyVaultIdentityClientId);

    const containerClient = blobClient.getContainerClient("my-container");
    const exists = await containerClient.exists();
    console.log("Container accessed with identity:", storageIdentityClientId);
  } catch (error) {
    console.error("Error:", error);
    throw error;
  }
}

// ============================================================================
// 3. LOCAL DEVELOPMENT FALLBACK
// ============================================================================

/**
 * DefaultAzureCredential with user-assigned identity hint
 * Works in Azure with user-assigned identity, falls back to Azure CLI locally
 */
async function useDefaultWithUserAssignedHint(): Promise<void> {
  const clientId = process.env.MANAGED_IDENTITY_CLIENT_ID;

  // If clientId is provided, DefaultAzureCredential will use it for managed identity
  const credential = new DefaultAzureCredential({
    managedIdentityClientId: clientId
  });

  const vaultUrl = "https://my-keyvault.vault.azure.net";
  const client = new SecretClient(vaultUrl, credential);

  try {
    const secret = await client.getSecret("my-secret-name");
    console.log("Secret retrieved successfully");
  } catch (error) {
    console.error("Authentication failed:", error);
    throw error;
  }
}

/**
 * Environment-based credential selection
 * Uses user-assigned identity in Azure, Azure CLI locally
 */
function createEnvironmentAwareCredential(): ManagedIdentityCredential | any {
  const { AzureCliCredential } = require("@azure/identity");

  const isRunningInAzure = 
    process.env.WEBSITE_INSTANCE_ID || 
    process.env.CONTAINER_APP_NAME ||
    process.env.FUNCTIONS_WORKER_RUNTIME;

  if (isRunningInAzure) {
    const clientId = process.env.MANAGED_IDENTITY_CLIENT_ID;

    if (!clientId) {
      throw new Error(
        "Running in Azure but MANAGED_IDENTITY_CLIENT_ID not set. " +
        "Set this environment variable to your user-assigned identity client ID."
      );
    }

    console.log("Using user-assigned managed identity:", clientId);
    return new ManagedIdentityCredential({ clientId });
  } else {
    console.log("Using Azure CLI credential for local development");
    return new AzureCliCredential();
  }
}

// ============================================================================
// 4. CONFIGURATION PATTERNS
// ============================================================================

/**
 * Configuration interface for managed identity
 */
interface ManagedIdentityConfig {
  type: "system-assigned" | "user-assigned";
  clientId?: string;
  resourceId?: string;
}

/**
 * Factory function to create appropriate credential based on configuration
 */
function createManagedIdentityFromConfig(
  config: ManagedIdentityConfig
): ManagedIdentityCredential {
  if (config.type === "system-assigned") {
    console.log("Creating system-assigned managed identity credential");
    return new ManagedIdentityCredential();
  }

  if (config.type === "user-assigned") {
    if (config.clientId) {
      console.log("Creating user-assigned managed identity with client ID:", config.clientId);
      return new ManagedIdentityCredential({ clientId: config.clientId });
    } else if (config.resourceId) {
      console.log("Creating user-assigned managed identity with resource ID");
      return new ManagedIdentityCredential({ resourceId: config.resourceId });
    } else {
      throw new Error(
        "User-assigned identity requires either clientId or resourceId"
      );
    }
  }

  throw new Error(`Unknown identity type: ${config.type}`);
}

/**
 * Load configuration from environment variables
 */
function loadManagedIdentityConfigFromEnv(): ManagedIdentityConfig {
  const identityType = process.env.MANAGED_IDENTITY_TYPE || "system-assigned";

  if (identityType === "user-assigned") {
    const clientId = process.env.MANAGED_IDENTITY_CLIENT_ID;
    const resourceId = process.env.MANAGED_IDENTITY_RESOURCE_ID;

    if (!clientId && !resourceId) {
      throw new Error(
        "User-assigned identity requires MANAGED_IDENTITY_CLIENT_ID " +
        "or MANAGED_IDENTITY_RESOURCE_ID environment variable"
      );
    }

    return {
      type: "user-assigned",
      clientId,
      resourceId
    };
  }

  return { type: "system-assigned" };
}

// ============================================================================
// 5. ERROR HANDLING SPECIFIC TO USER-ASSIGNED IDENTITY
// ============================================================================

/**
 * Comprehensive error handling for user-assigned managed identity
 */
async function robustUserAssignedIdentityUsage(): Promise<void> {
  const clientId = process.env.MANAGED_IDENTITY_CLIENT_ID;

  if (!clientId) {
    throw new Error(
      "MANAGED_IDENTITY_CLIENT_ID environment variable is required for user-assigned identity"
    );
  }

  const vaultUrl = "https://my-keyvault.vault.azure.net";

  try {
    const credential = new ManagedIdentityCredential({ clientId });
    const client = new SecretClient(vaultUrl, credential);

    const secret = await client.getSecret("my-secret-name");
    console.log("Success:", secret.name);

  } catch (error: any) {
    if (error.code === "ManagedIdentityCredential_Timeout") {
      console.error("Timeout: Managed identity endpoint not responding");
      console.error("Possible causes:");
      console.error("  - Not running on Azure resource with managed identity enabled");
      console.error("  - User-assigned identity not assigned to this resource");
      console.error("  - Incorrect client ID");
    } else if (error.code === "CredentialUnavailable") {
      console.error("User-assigned managed identity not available");
      console.error("Ensure the identity is assigned to your Azure resource");
      console.error("Client ID used:", clientId);
    } else if (error.statusCode === 403) {
      console.error("Access denied: User-assigned identity lacks required permissions");
      console.error("Grant appropriate RBAC role to the identity:", clientId);
    } else if (error.message?.includes("Invalid client ID")) {
      console.error("Invalid client ID format:", clientId);
      console.error("Client ID should be a GUID (e.g., 12345678-1234-1234-1234-123456789abc)");
    } else {
      console.error("Unexpected error:", error.message);
      console.error("Full error:", error);
    }

    throw error;
  }
}

/**
 * Validate user-assigned identity configuration
 */
function validateUserAssignedIdentityConfig(clientId: string): void {
  // Basic GUID format validation
  const guidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

  if (!guidPattern.test(clientId)) {
    throw new Error(
      `Invalid client ID format: ${clientId}. ` +
      `Expected a GUID (e.g., 12345678-1234-1234-1234-123456789abc)`
    );
  }

  console.log("✓ Client ID format is valid");
}

/**
 * Test user-assigned identity availability and configuration
 */
async function testUserAssignedIdentity(clientId: string): Promise<boolean> {
  try {
    validateUserAssignedIdentityConfig(clientId);

    const credential = new ManagedIdentityCredential({ clientId });

    // Try to get a token
    const token = await credential.getToken("https://management.azure.com/.default");

    if (token && token.token) {
      console.log("✓ User-assigned managed identity is working");
      console.log("Client ID:", clientId);
      console.log("Token expires at:", new Date(token.expiresOnTimestamp));
      return true;
    }

    return false;
  } catch (error: any) {
    console.log("✗ User-assigned managed identity test failed:", error.message);
    return false;
  }
}

