 * 
 * For VM:
 * az vm identity assign \
 *   --name <vm-name> \
 *   --resource-group <rg> \
 *   --identities /subscriptions/<sub>/resourceGroups/<rg>/providers/Microsoft.ManagedIdentity/userAssignedIdentities/<name>
 */

/**
 * PITFALL #3: Multiple identities assigned but not specifying which to use
 * Solution: Always specify clientId when using user-assigned identity
 */

/**
 * PITFALL #4: Confusing client ID with object ID (principal ID)
 * Solution: Use CLIENT ID (Application ID), not Object ID, with ManagedIdentityCredential
 */

