 * System-Assigned vs User-Assigned Managed Identity
 * Comparison, Best Practices, and Decision Guide
 */

import { ManagedIdentityCredential, DefaultAzureCredential } from "@azure/identity";

// ============================================================================
// COMPARISON: SYSTEM-ASSIGNED VS USER-ASSIGNED
// ============================================================================

/**
 * SYSTEM-ASSIGNED MANAGED IDENTITY
 * 
 * Pros:
 * - Simpler to set up (no need to specify identity)
 * - Automatically created with the resource
 * - Automatically deleted when resource is deleted
 * - No separate Azure resource to manage
 * - Perfect for 1:1 resource-to-identity relationships
 * 
 * Cons:
 * - Tied to the lifecycle of a single resource
 * - Cannot be shared across multiple resources
 * - Loses all permissions when resource is deleted
 * - Harder to pre-configure permissions before resource creation
 * - Cannot be created separately from the resource
 * 
 * Use When:
 * - Single Azure resource needs its own identity
 * - Identity permissions are specific to that resource
 * - Resource lifecycle matches identity lifecycle
 * - Simplicity is preferred over flexibility
 */
function createSystemAssignedExample() {
  // No parameters needed - uses the identity attached to the resource
  return new ManagedIdentityCredential();
}

/**
 * USER-ASSIGNED MANAGED IDENTITY
 * 
 * Pros:
 * - Can be shared across multiple resources
 * - Independent lifecycle (survives resource deletion)
 * - Can be pre-created with permissions before assigning to resources
 * - Better for multi-resource scenarios
 * - Easier to rotate or update permissions centrally
 * - Can be used in disaster recovery scenarios
 * 
 * Cons:
 * - Requires explicit client ID specification
 * - Additional Azure resource to manage
 * - Must be explicitly assigned to resources
 * - Slightly more complex configuration
 * 
 * Use When:
