}

// ============================================================================
// DECISION MATRIX
// ============================================================================

interface IdentityRequirements {
  multipleResources: boolean;
  persistBeyondResourceDeletion: boolean;
  preConfigurePermissions: boolean;
  simplicity: boolean;
  blueGreenDeployment: boolean;
}

function recommendIdentityType(requirements: IdentityRequirements): string {
  // User-assigned if any of these are true
  if (
    requirements.multipleResources ||
    requirements.persistBeyondResourceDeletion ||
    requirements.preConfigurePermissions ||
    requirements.blueGreenDeployment
  ) {
    return "user-assigned";
  }

  // System-assigned for simplicity
  if (requirements.simplicity) {
    return "system-assigned";
  }

  // Default to system-assigned for single-resource scenarios
  return "system-assigned";
}

// Example usage
const recommendation1 = recommendIdentityType({
  multipleResources: false,
  persistBeyondResourceDeletion: false,
  preConfigurePermissions: false,
  simplicity: true,
  blueGreenDeployment: false
});
console.log("Recommendation:", recommendation1); // "system-assigned"

