  multipleResources: true,
  persistBeyondResourceDeletion: true,
  preConfigurePermissions: true,
  simplicity: false,
  blueGreenDeployment: true
});
console.log("Recommendation:", recommendation2); // "user-assigned"

// ============================================================================
// BEST PRACTICES
