/**
 * BEST PRACTICE #1: Use DefaultAzureCredential for maximum flexibility
 * Works both in Azure and local development
 */
function bestPracticeDefaultCredential() {
  // Works with both system-assigned and user-assigned identities
  // Falls back to Azure CLI for local development
  const credential = new DefaultAzureCredential({
    // Optional: Specify client ID if using user-assigned identity
    managedIdentityClientId: process.env.MANAGED_IDENTITY_CLIENT_ID
  });

  return credential;
}

/**
