 */
const MANAGED_IDENTITY_CONFIG = {
  // Type of identity
  type: process.env.MANAGED_IDENTITY_TYPE || "system-assigned",

  // Client ID for user-assigned identity
  clientId: process.env.MANAGED_IDENTITY_CLIENT_ID,

  // Resource ID for user-assigned identity (alternative)
  resourceId: process.env.MANAGED_IDENTITY_RESOURCE_ID
} as const;

