 * BEST PRACTICE #3: Create a credential factory function
 */
function createCredential() {
  if (MANAGED_IDENTITY_CONFIG.type === "user-assigned") {
    if (MANAGED_IDENTITY_CONFIG.clientId) {
      return new ManagedIdentityCredential({
        clientId: MANAGED_IDENTITY_CONFIG.clientId
      });
    }
    if (MANAGED_IDENTITY_CONFIG.resourceId) {
      return new ManagedIdentityCredential({
        resourceId: MANAGED_IDENTITY_CONFIG.resourceId
      });
    }
    throw new Error(
      "User-assigned identity requires MANAGED_IDENTITY_CLIENT_ID or MANAGED_IDENTITY_RESOURCE_ID"
    );
