    return token;
  } catch (error: any) {
    // Log detailed error information
    console.error("Managed Identity Error:", {
      message: error.message,
      code: error.code,
      statusCode: error.statusCode,
      identityType: MANAGED_IDENTITY_CONFIG.type,
      clientId: MANAGED_IDENTITY_CONFIG.clientId
    });

    // Provide actionable error messages
    if (error.code === "CredentialUnavailable") {
      throw new Error(
        "Managed identity is not available. Ensure it is enabled on the Azure resource."
      );
    }

    if (error.statusCode === 403) {
      throw new Error(
